import fs from'node:fs';import{loadAnny,loadMHR}from'../teachers.mjs';
const a=loadAnny(),m=loadMHR(),out=new URL('../research/geometry/',import.meta.url);const masks={};for(const[name,engine,labels]of[['anny',a,a.boneLabels],['mhr',m,m.meta.joint_names]]){const weight=new Float32Array((name==='anny'?a.vertexCount:m.meta.vertices)*2),indices=[labels.indexOf(name==='anny'?'eye.L':'l_eye'),labels.indexOf(name==='anny'?'eye.R':'r_eye')];if(name==='anny'){for(let v=0;v<a.vertexCount;v++)for(let k=0;k<a.influences;k++){const j=a.arrays.vertex_bone_indices[v*a.influences+k],w=a.arrays.vertex_bone_weights[v*a.influences+k];indices.forEach((b,eye)=>{if(j===b)weight[v*2+eye]+=w;});}}else for(let k=0;k<m.d.skin_weights.length;k++)indices.forEach((b,eye)=>{if(m.d.skin_joints[k]===b)weight[m.d.skin_verts[k]*2+eye]+=m.d.skin_weights[k];});fs.writeFileSync(new URL(name+'-eye-weights.f32',out),new Uint8Array(weight.buffer));masks[name]={indices,counts:indices.map((_,i)=>Array.from(weight).filter((w,k)=>k%2===i&&w>.9).length)};}fs.writeFileSync(new URL('semantic-mask-report.json',out),JSON.stringify(masks,null,2));console.log(masks);
